function legendLevel(){return p.xp<8500?0:Math.floor((p.xp-8500)/1500)+1}
function legendNext(){let lv=legendLevel();return lv?8500+lv*1500:8500}
function legendTitle(lv=legendLevel()){if(lv>=50)return 'Imortal Alvinegro';if(lv>=25)return 'Ícone Eterno';if(lv>=10)return 'Lenda Gloriosa';if(lv>=5)return 'Guardião Alvinegro';return lv?'Lenda em Ascensão':'Rumo à Lenda'}
