function careerStars(){let c=p.career&&p.career.best?p.career.best:{};return Object.values(c).reduce((a,n)=>a+(n>=5?3:n>=4?2:n>=3?1:0),0)}
function legendMilestones(){let lv=legendLevel(),marks=[[5,'⭐','Guardião Alvinegro'],[10,'🏆','Lenda Gloriosa'],[25,'💠','Ícone Eterno'],[50,'♛','Imortal Alvinegro']];return `<div class="legendMilestones">${marks.map(([n,ic,t])=>`<span class="${lv>=n?'done':''}"><i>${ic}</i><b>Lenda ${n}</b><small>${t}</small></span>`).join('')}</div>`}
