function eventData(){p.events=p.events||{completed:[],best:{},grandClaimed:false};p.events.completed=p.events.completed||[];p.events.best=p.events.best||{};if(typeof p.events.grandClaimed!=='boolean')p.events.grandClaimed=false;return p.events}
function eventHub(){let e=eventData();app.innerHTML=header()+`<section class="hub eventHub"><span class="eyebrow">⚡ TEMPORADAS DE LENDA</span><h1>EVENTOS HISTÓRICOS</h1><p>Rodadas curtas inspiradas em capítulos marcantes. Faça pelo menos 4/5 para conquistar o evento e receber o bônus único.</p><div class="eventProgress"><b>${e.completed.length}/${EVENTS.length} EVENTOS CONQUISTADOS</b><span><i style="width:${Math.round(e.completed.length/EVENTS.length*100)}%"></i></span><small>${e.completed.length===EVENTS.length?'Coleção histórica completa!':'Conquiste todos para completar a galeria de épocas.'}</small></div><div class="eventGrid">${EVENTS.map(v=>{let best=e.best[v.id]||0,done=e.completed.includes(v.id);return `<button class="eventCard ${done?'done':''}" data-event="${v.id}"><span>${v.icon}</span><div><small>${v.year} • EVENTO ESPECIAL</small><b>${v.title}</b><p>${v.desc}</p><em>${done?'✓ CONQUISTADO • melhor '+best+'/5':'BÔNUS: +'+v.bonus[0]+' XP • 🪙 '+v.bonus[1]+' • ⭐ '+v.bonus[2]}</em></div><strong>›</strong></button>`}).join('')}</div><div class="eventSeasonReward ${e.completed.length===EVENTS.length?'ready':''}"><i>♛</i><div><small>RECOMPENSA DA TEMPORADA</small><b>Guardião das Eras</b><span>${e.grandClaimed?'✓ Recompensa conquistada':e.completed.length===EVENTS.length?'Será liberada ao concluir o último evento':'Conquiste os 3 eventos • +750 XP • 🪙 300 • ⭐ 5'}</span></div></div><div class="eventNote">★ Os bônus especiais são recebidos uma vez. Depois, você pode refazer qualquer evento para melhorar sua melhor nota.</div><button class="secondary" id="eventBack">VOLTAR AOS MODOS</button></section>${bottomNav('play')}`;bind();bindNav();document.querySelectorAll('[data-event]').forEach(b=>b.onclick=()=>eventIntro(b.dataset.event));document.querySelector('#eventBack').onclick=categoryHub}
function eventIntro(id){let v=EVENTS.find(x=>x.id===id),e=eventData(),done=e.completed.includes(id);app.innerHTML=header()+`<section class="careerIntro eventIntro"><span class="eyebrow">${v.icon} ${v.year} • EVENTO HISTÓRICO</span><div class="careerSeal">${v.icon}</div><h1>${v.title.toUpperCase()}</h1><p>${v.desc}</p><div class="careerRules"><span>5 perguntas</span><span>3 vidas</span><span>Meta 4/5</span></div><div class="eventReward"><small>${done?'EVENTO JÁ CONQUISTADO':'BÔNUS DA PRIMEIRA CONQUISTA'}</small><b>🔥 ${v.bonus[0]} XP &nbsp; 🪙 ${v.bonus[1]} &nbsp; ⭐ ${v.bonus[2]}</b></div><button class="primary" id="eventGo">${done?'JOGAR NOVAMENTE':'COMEÇAR EVENTO'} ›</button><button class="secondary" id="eventCancel">VOLTAR</button></section>${bottomNav('play')}`;bind();bindNav();document.querySelector('#eventGo').onclick=()=>eventStart(id);document.querySelector('#eventCancel').onclick=eventHub}
function eventStart(id){let v=EVENTS.find(x=>x.id===id);eventActive=id;careerActive=null;selectedDifficulty='Evento';selectedCategory='Misto';qs=v.q.map(idx=>{let q=[...Q[idx]];q._idx=idx;return q});i=0;score=0;lives=3;locked=false;streak=0;bestRun=0;fastCorrect=0;game()}
