function careerData(){p.career=p.career||{completed:[],best:{}};p.career.completed=p.career.completed||[];p.career.best=p.career.best||{};return p.career}
function careerStars(best){return best>=5?3:best>=4?2:best>=3?1:0}
function careerHub(){let c=careerData(),done=c.completed.length,all=done===CAREER.length,totalStars=CAREER.reduce((a,ch)=>a+careerStars(c.best[ch.id]||0),0);app.innerHTML=header()+`<section class="hub careerHub"><span class="eyebrow">★ MODO CARREIRA ALVINEGRA</span><h1>MAPA DA HISTÓRIA</h1><p>Reviva a trajetória do Glorioso. Cada capítulo guarda sua melhor nota e até três estrelas.</p><div class="careerProgress"><b>${done}/${CAREER.length} capítulos concluídos</b><span><i style="width:${done/CAREER.length*100}%"></i></span><em>★ ${totalStars}/${CAREER.length*3} estrelas conquistadas</em></div><div class="careerMap">${CAREER.map((ch,n)=>{let open=n===0||c.completed.includes(CAREER[n-1].id),finished=c.completed.includes(ch.id),best=c.best[ch.id]||0,stars=careerStars(best);return `<button data-ch="${ch.id}" ${open?'':'disabled'} class="careerNode ${finished?'done':''} ${open?'open':'locked'}"><span class="careerPathIcon">${open?ch.icon:'🔒'}</span><div class="careerNodeBody"><small>CAPÍTULO ${n+1} • ${ch.years}</small><b>${ch.title}</b><div class="careerStars">${[1,2,3].map(x=>`<i class="${x<=stars?'on':''}">★</i>`).join('')} <em>${best?`melhor ${best}/5 • toque para refazer`:open?'pronto para jogar':'bloqueado'}</em></div></div><strong>${finished?'✓':open?'›':'🔒'}</strong></button>`}).join('')}</div><div class="careerFinal ${all?'unlocked':'locked'}"><i>🏆</i><div><small>RECOMPENSA FINAL</small><b>Guardião da História Alvinegra</b><span>${all?'Conquista desbloqueada! Você completou toda a Carreira.':`Conclua os ${CAREER.length} capítulos para desbloquear.`}</span></div></div><button class="secondary" id="careerBack">VOLTAR AOS MODOS</button></section>${bottomNav('play')}`;bind();bindNav();document.querySelectorAll('[data-ch]').forEach(b=>b.onclick=()=>careerIntro(b.dataset.ch));document.querySelector('#careerBack').onclick=categoryHub}
function careerIntro(id){let ch=CAREER.find(x=>x.id===id);if(!ch)return;app.innerHTML=header()+`<section class="hub careerIntro"><span class="eyebrow">CAPÍTULO ${CAREER.indexOf(ch)+1} • ${ch.years}</span><div class="careerSeal">${ch.icon}</div><h1>${ch.title.toUpperCase()}</h1><p>${ch.intro}</p><div class="careerRules"><span>5 perguntas</span><span>3 vidas</span><span>+ XP e moedas</span></div><button class="primary" id="careerGo">COMEÇAR CAPÍTULO ›</button><button class="secondary" id="careerCancel">VOLTAR</button></section>${bottomNav('play')}`;bind();bindNav();document.querySelector('#careerGo').onclick=()=>careerStart(id);document.querySelector('#careerCancel').onclick=careerHub}
function careerStart(id){let ch=CAREER.find(x=>x.id===id);careerActive=id;selectedDifficulty='Médio';selectedCategory='Misto';qs=ch.q.map(idx=>{let q=[...Q[idx]];q._idx=idx;return q});i=0;score=0;lives=3;locked=false;streak=0;bestRun=0;fastCorrect=0;game()}

function rulesModal(){let back=document.createElement('div');back.className='modalBack';back.innerHTML=`<div class="modal rulesModal"><span class="eyebrow">★ MANUAL ALVINEGRO</span><h2>COMO JOGAR</h2><div class="rulesList"><article><b>01 • PARTIDA</b><span>Responda às perguntas antes de perder suas 3 vidas. Cada modo informa a quantidade de questões.</span></article><article><b>02 • COMBO</b><span>3 acertos seguidos ativam ×1,25; 5 chegam a ×1,5; 8 ou mais levam ao combo máximo ×2.</span></article><article><b>03 • RESPOSTA PERFEITA</b><span>Acertar rapidamente pode render bônus extra de XP.</span></article><article><b>04 • PROGRESSÃO</b><span>XP aumenta seu nível; moedas compram cosméticos; estrelas registram grandes desempenhos.</span></article><article><b>05 • APRENDIZADO</b><span>Perguntas erradas entram no Treino de Revisão para você tentar novamente.</span></article><article><b>06 • OBJETIVO FINAL</b><span>Complete Carreira, Eventos, Coleção, domínio e demais metas da Central de Conclusão.</span></article></div><button class="primary full" id="closeRules">ENTENDI ›</button></div>`;document.body.append(back);back.querySelector('#closeRules').onclick=()=>back.remove();back.onclick=e=>{if(e.target===back)back.remove()}}
function start(){categoryHub()}
function legacyDifficulty(){app.innerHTML=header()+`<section class="difficultyPick"><span class="eyebrow">ESCOLHA O DESAFIO</span><h2>Qual é o seu nível alvinegro?</h2><p>Quanto maior o desafio, maior a recompensa.</p><div class="difficultyGrid">${Object.entries(DIFF).filter(([name])=>!['Evento','Revisão'].includes(name)).map(([name,d])=>`<button data-d="${name}"><b>${d.stars} ${name}</b><small>${d.desc}</small><em>${d.detail}</em><span class="rewardTag">${d.mult===1?'XP normal':d.mult+'× XP'}</span></button>`).join('')}</div><div class="legendaryNote">🏆 <b>Lendário</b> é o desafio máximo: sem perguntas fáceis e com a maior recompensa.</div></section>${bottomNav('play')}`;bind();bindNav();document.querySelectorAll('.difficultyGrid button').forEach(b=>b.onclick=()=>startDifficulty(b.dataset.d))}
function startDifficulty(d){selectedDifficulty=d;let candidates=Q.map((q,idx)=>({q,idx}));if(selectedCategory!=='Misto')candidates=candidates.filter(o=>categoryKey(o.q[0])===selectedCategory);let pool;if(d==='Lendário')pool=candidates.filter(o=>['Médio','Difícil'].includes(o.q[4]));else{pool=candidates.filter(o=>o.q[4]===d);if(pool.length<10)pool=candidates.filter(o=>d==='Difícil'?['Médio','Difícil'].includes(o.q[4]):d==='Médio'?['Fácil','Médio'].includes(o.q[4]):o.q[4]==='Fácil')}let unseen=sh(pool.filter(o=>!p.seenQ.includes(o.idx))),seen=sh(pool.filter(o=>p.seenQ.includes(o.idx)));if(unseen.length<10&&p.seenQ.length>24){p.seenQ=p.seenQ.slice(-24);unseen=sh(pool.filter(o=>!p.seenQ.includes(o.idx)));seen=sh(pool.filter(o=>p.seenQ.includes(o.idx)));}let picked=[...unseen,...seen].slice(0,10);if(picked.length<10){let extra=sh(candidates.filter(o=>!picked.some(z=>z.idx===o.idx)));picked.push(...extra.slice(0,10-picked.length))}qs=sh(picked).map(o=>{let q=[...o.q];q._idx=o.idx;return q});i=0;score=0;lives=3;locked=false;streak=0;bestRun=0;fastCorrect=0;game()}
function game(){let q=qs[i];questionStarted=Date.now();app.innerHTML=header()+`<section class="game"><div class="gameTop"><div><span>PERGUNTA ${String(i+1).padStart(2,'0')}</span><b>${i+1} <small>/ ${qs.length}</small></b></div><div class="lives">${[0,1,2].map(k=>k<lives?'❤️':'♡').join(' ')}</div><div class="xp">🔥 +${Math.round(score*100*(selectedDifficulty==='Diário'?1:DIFF[selectedDifficulty].mult))} XP</div></div><div class="bar"><i style="width:${i/qs.length*100}%"></i></div><div class="card"><span class="category">${q[0].toUpperCase()}</span><span class="difficultyBadge">${q[4]}</span><h2>${q[1]}</h2><div class="answers">${q[2].map((o,k)=>`<button data-k="${k}"><span>${'ABCD'[k]}</span>${o}</button>`).join('')}</div></div><div class="comboMeter ${streak>=3?'hot':''}"><span>COMBO</span><b>${streak>=8?'×2.0':streak>=5?'×1.5':streak>=3?'×1.25':'×1.0'}</b><small>${streak<3?`${3-streak} acertos para ativar`:streak<5?`${5-streak} para ×1.5`:streak<8?`${8-streak} para ×2.0`:'COMBO MÁXIMO'}</small></div><div class="mini"><span class="playerMini ${equipClass()}">${avatarSVG(p.avatar,true)} ${p.name}</span><span>${score} acertos • sequência ${streak} • ${lives} vidas</span></div></section>`;bind();document.querySelectorAll('.answers button').forEach(b=>b.onclick=()=>choose(+b.dataset.k))}
function choose(k){if(locked)return;locked=true;let q=qs[i],ok=k===q[3],fast=ok&&(Date.now()-questionStarted<=4500);if(fast)fastCorrect++;sfx(ok?(streak>=4?'streak':'ok'):'no');if(Number.isInteger(q._idx)){p.seenQ=p.seenQ.filter(x=>x!==q._idx);p.seenQ.push(q._idx);if(p.seenQ.length>36)p.seenQ=p.seenQ.slice(-36);save();}if(Number.isInteger(q._idx)){p.reviewMissed=p.reviewMissed||[];if(ok&&q._review&&p.reviewMissed.includes(q._idx)){p.reviewMissed=p.reviewMissed.filter(x=>x!==q._idx);p.reviewCleared=(p.reviewCleared||0)+1}else if(!ok&&!p.reviewMissed.includes(q._idx)){p.reviewMissed.push(q._idx);if(p.reviewMissed.length>40)p.reviewMissed=p.reviewMissed.slice(-40)}save();}if(ok){score++;streak++;bestRun=Math.max(bestRun,streak)}else{lives--;streak=0}document.querySelectorAll('.answers button').forEach((b,j)=>{if(j===q[3])b.classList.add('correct');else if(j===k)b.classList.add('wrong');else b.classList.add('muted')});let box=document.createElement('div');box.className='feedbackBox '+(ok?'ok':'no');box.innerHTML=`<b>${ok?'✓ Resposta certa!':'✕ Não foi dessa vez.'}</b>${ok&&streak>=3?`<div class="streakFlash">🔥 COMBO ${streak>=8?'×2.0':streak>=5?'×1.5':'×1.25'} • SEQUÊNCIA ${streak}!</div>`:''}${fast?'<div class="fastBonus">⚡ RESPOSTA PERFEITA +25 XP</div>':''}<p>${q[5]}</p><button class="nextBtn">${i<qs.length-1&&lives>0?'PRÓXIMA PERGUNTA ›':'VER RESULTADO ›'}</button>`;document.querySelector('.card').append(box);box.querySelector('button').onclick=()=>{if(i<qs.length-1&&lives>0){i++;locked=false;game()}else finish()}}
function finish(){let oldLevel=li(),oldXp=p.xp,oldPrestige=prestigeIndex(),oldLegend=legendLevel(),isDaily=selectedDifficulty==='Diário',isReview=selectedDifficulty==='Revisão',isSpecial=!!eventActive||!!careerActive||isReview,mult=isDaily?1:DIFF[selectedDifficulty].mult,streakBonus=bestRun>=8?250:bestRun>=5?150:bestRun>=3?60:0,fastBonus=fastCorrect*25,xp=isDaily?(score*100+dailyReward()+fastBonus):Math.round((score*100+(score===10?250:0)+streakBonus+fastBonus)*mult),coins=isDaily?(score*15+25):Math.round((score*12+(score>=8?40:0)+(bestRun>=5?25:0))*Math.min(mult,1.5)),stars=isDaily?(score===5?2:score>=3?1:0):(isSpecial?0:((score>=9?3:score>=7?2:score>=5?1:0)+(selectedDifficulty==='Lendário'&&score>=8?1:0))),eventResult=null;if(eventActive){let ed=eventData(),ev=EVENTS.find(x=>x.id===eventActive),was=ed.completed.includes(eventActive),passed=score>=4;ed.best[eventActive]=Math.max(ed.best[eventActive]||0,score);if(passed&&!was){ed.completed.push(eventActive);xp+=ev.bonus[0];coins+=ev.bonus[1];stars+=ev.bonus[2]}let grand=false;if(ed.completed.length===EVENTS.length&&!ed.grandClaimed){ed.grandClaimed=true;grand=true;xp+=750;coins+=300;stars+=5}eventResult={passed,first:passed&&!was,title:ev.title,bonus:ev.bonus,grand};eventActive=null;}p.xp+=xp;p.coins+=coins;p.stars+=stars;p.best=Math.max(p.best,score);p.games++;p.totalCorrect+=score;p.totalAnswered=(p.totalAnswered||0)+qs.length;ensureWeekly();p.weekly.games++;p.weekly.correct+=score;if(selectedDifficulty==='Difícil')p.weekly.difficult++;if(isDaily)p.weekly.daily++;if(!isDaily&&!isSpecial)p.difficultyGames[selectedDifficulty]=(p.difficultyGames[selectedDifficulty]||0)+1;p.bestStreak=Math.max(p.bestStreak,bestRun);if(score===10)p.perfect++;if(selectedDifficulty==='Lendário'&&score===10)p.legendaryPerfect=(p.legendaryPerfect||0)+1;if(isDaily){let today=dateKey();p.dailyStreak=(p.lastDailyDate===yesterdayKey())?(p.dailyStreak||0)+1:1;p.lastDailyDate=today;p.daily={date:today,played:true,score:score,streak:bestRun};if(p.dailyStreak>0&&p.dailyStreak%7===0){coins+=250;stars+=5;p.coins+=250;p.stars+=5;}}if(lives===3)p.flawless=(p.flawless||0)+1;if(selectedDifficulty==='Difícil'&&score>=7)p.difficultWins++;if(selectedDifficulty==='Lendário'&&score>=7)p.legendaryWins++;let careerResult=null;if(careerActive){let cd=careerData(),id=careerActive,wasDone=cd.completed.includes(id);cd.best[id]=Math.max(cd.best[id]||0,score);if(score>=3&&!wasDone)cd.completed.push(id);careerResult={id,passed:score>=3,newlyCompleted:score>=3&&!wasDone};careerActive=null;}if(!isDaily&&selectedCategory!=='Misto'){p.categoryStats=p.categoryStats||{};let cs=p.categoryStats[selectedCategory]||{games:0,correct:0,answered:0};cs.games++;cs.correct+=score;cs.answered+=qs.length;p.categoryStats[selectedCategory]=cs;updateCollection();}unlock();let x=li(),leveled=x>oldLevel,podium=oldXp<2500&&p.xp>=2500,pr=prestige(),newPrestige=prestigeIndex(),prestigeUp=newPrestige>oldPrestige&&oldPrestige>=0,newLegend=legendLevel(),legendUp=newLegend>oldLegend&&oldLegend>0;if(score===10)sfx('perfect');app.innerHTML=header()+`<section class="result ${score===10?'perfectResult':''}"><div class="cup">🏆</div><span class="eyebrow">FASE CONCLUÍDA</span><h1>${careerResult?(score===5?'PERFEITO! ⭐':score===4?'FOGO NELES!':score===3?'MISSÃO CUMPRIDA!':'NÃO DESISTA!'):(score>=9?'LENDA!':score>=7?'FOGO NELES!':score>=4?'BOA, ALVINEGRO!':'NÃO DESISTA!')}</h1><p>Você acertou <strong>${score} de ${qs.length}</strong> • melhor sequência: <strong>${bestRun}</strong>${fastCorrect?` • ⚡ ${fastCorrect} respostas perfeitas`:''}</p>${eventResult?`<div class="eventResult ${eventResult.passed?'win':'retry'}"><b>${eventResult.passed?'★ EVENTO CONQUISTADO':'EVENTO INCOMPLETO'}</b><span>${eventResult.passed?(eventResult.first?'Bônus histórico recebido!':'Melhor nota registrada.'): 'Faça 4/5 para conquistar este evento.'}</span></div>${eventResult.first?`<div class="rewardBreakdown"><b>DETALHE DA RECOMPENSA</b><span>Partida: +${xp-eventResult.bonus[0]-(eventResult.grand?750:0)} XP • 🪙 ${coins-eventResult.bonus[1]-(eventResult.grand?300:0)} • ⭐ ${stars-eventResult.bonus[2]-(eventResult.grand?5:0)}</span><span>Evento: +${eventResult.bonus[0]} XP • 🪙 ${eventResult.bonus[1]} • ⭐ ${eventResult.bonus[2]}</span>${eventResult.grand?'<span>Temporada completa: +750 XP • 🪙 300 • ⭐ 5</span>':''}</div>`:''}${eventResult.grand?'<div class="seasonComplete">♛ <b>GUARDIÃO DAS ERAS</b><span>Você conquistou todos os Eventos Históricos!</span></div>':''}`:''}${streakBonus?`<div class="comboReward">🔥 BÔNUS DE COMBO <b>+${Math.round(streakBonus*mult)} XP</b> • melhor sequência ${bestRun}</div>`:''}${careerResult&&careerResult.passed?`<div class="careerSuccess">🏆 <b>CAPÍTULO CONCLUÍDO</b><span>${careerResult.newlyCompleted?'Próximo capítulo desbloqueado!':'Etapa concluída novamente.'}</span></div>`:(careerResult?'<div class="careerRetry">Faltou pouco: faça pelo menos 3/5 para liberar o próximo capítulo.</div>':'')}${score===10?'<div class="perfectBanner">★ 10/10 — PARTIDA PERFEITA ★</div>':''}<div class="rewards"><div>🔥<b>+${xp}</b><small>XP</small></div><div>🪙<b>+${coins}</b><small>MOEDAS</small></div><div>⭐<b>+${stars}</b><small>ESTRELAS</small></div></div><div class="resultLevel"><small>AGORA VOCÊ É</small><b>${stageSVG(L[x][2])} ${L[x][0]}</b>${pr?`<em>${pr[2]} PRESTÍGIO ${pr[0].toUpperCase()}</em>`:''}</div>${prestigePanel()}${journey()}${challenges()}${achievements()}<div class="actions"><button class="secondary" id="home">⌂ INÍCIO</button><button class="primary" id="again">↻ JOGAR NOVAMENTE</button></div></section>${podium?celebration('🏆','PÓDIO GLORIOSO','Você chegou ao topo da jornada! Agora começa sua trilha de Prestígio.'):(prestigeUp?celebration(PRESTIGE[newPrestige][2],'PRESTÍGIO '+PRESTIGE[newPrestige][0].toUpperCase(),newPrestige===3?`Você alcançou o topo do Prestígio! ${PRESTIGE[newPrestige][3]} desbloqueada. Agora começa sua jornada Lenda Alvinegra.`:`Recompensa desbloqueada: ${PRESTIGE[newPrestige][3]}.`):(legendUp?(newLegend-oldLegend>1?celebration('✦','ASCENSÃO LENDÁRIA',`Você avançou ${newLegend-oldLegend} níveis de uma vez: Lenda ${oldLegend} → Lenda ${newLegend}! Título atual: ${legendTitle(newLegend)}.`):celebration(legendBadge(newLegend),'LENDA ALVINEGRA '+newLegend,`Novo nível alcançado! Título atual: ${legendTitle(newLegend)}.`)):(leveled?celebration('★','NOVO NÍVEL!',`Você avançou para ${L[x][0]}.`):'')))}`;bind();document.querySelector('#home').onclick=home;document.querySelector('#again').onclick=isDaily?home:(isReview?categoryHub:start);let close=document.querySelector('#closeCelebration');if(close)close.onclick=()=>document.querySelector('.levelCelebration').remove()}
function celebration(icon,title,msg){return `<div class="levelCelebration"><div class="confetti">${'<i></i>'.repeat(18)}</div><div class="celebrateCard"><span>${icon}</span><small>CONQUISTA DESBLOQUEADA</small><h2>${title}</h2><p>${msg}</p><button id="closeCelebration" class="primary">CONTINUAR ›</button></div></div>`}
function profile(){let back=document.createElement('div');back.className='modalBack';let owned=new Set(p.ownedShop||[]),eq=p.equipped||{};let choices=type=>allCosmetics().filter(x=>x[1]===type&&owned.has(x[0])).map(x=>`<button type="button" data-cosmetic="${x[0]}" data-type="${type}" class="${eq[type]===x[0]?'selected':''}"><i>${x[2]}</i><span>${x[3]}</span></button>`).join('')||'<small class="emptyCosmetic">Nenhum item comprado ainda.</small>';back.innerHTML=`<div class="modal characterEditor"><span class="eyebrow">MEU JOGADOR</span><h2>Personalize seu Alvinegro</h2><div id="editorPreview" class="editorPreview ${equipClass()}">${avatarSVG(p.avatar)}<b>${p.name}</b><small>${playerTitle()}</small></div><label>Nome do jogador<input id="nm" maxlength="16" value="${p.name.replace(/"/g,'&quot;')}"></label><label>Avatar alvinegro</label><div class="avatars premiumAvatars">${AV.map(a=>`<button data-av="${a}" class="${a===p.avatar?'selected':''}">${avatarSVG(a)}</button>`).join('')}</div><div class="editorCosmetics"><h3>COSMÉTICOS DESBLOQUEADOS</h3>${[['frame','Moldura'],['title','Título'],['effect','Aura'],['uniform','Uniforme']].map(([t,n])=>`<label>${n}</label><div class="cosmeticChoices"><button type="button" data-none="${t}" class="${!eq[t]?'selected':''}">SEM ITEM</button>${choices(t)}</div>`).join('')}</div><button class="primary full" id="save">SALVAR PERSONALIZAÇÃO</button></div>`;document.body.append(back);let chosen=AV.includes(p.avatar)?p.avatar:'A',draft={...eq};let refresh=()=>{let pv=back.querySelector('#editorPreview'),cls=[draft.frame||'',draft.effect||'',draft.uniform||''].filter(Boolean).join(' '),ti=allCosmetics().find(x=>x[0]===draft.title);pv.className='editorPreview '+cls;pv.innerHTML=avatarSVG(chosen)+`<b>${back.querySelector('#nm').value.trim()||'Alvinegro'}</b><small>${ti?ti[3]:playerTitle()}</small>`};back.querySelectorAll('.avatars button').forEach(b=>b.onclick=()=>{chosen=b.dataset.av;back.querySelectorAll('.avatars button').forEach(x=>x.classList.toggle('selected',x===b));refresh()});back.querySelectorAll('[data-cosmetic]').forEach(b=>b.onclick=()=>{let t=b.dataset.type;draft[t]=b.dataset.cosmetic;back.querySelectorAll(`[data-type="${t}"],[data-none="${t}"]`).forEach(x=>x.classList.toggle('selected',x===b));refresh()});back.querySelectorAll('[data-none]').forEach(b=>b.onclick=()=>{let t=b.dataset.none;draft[t]='';back.querySelectorAll(`[data-type="${t}"],[data-none="${t}"]`).forEach(x=>x.classList.toggle('selected',x===b));refresh()});back.querySelector('#nm').oninput=refresh;back.querySelector('#save').onclick=()=>{p.name=back.querySelector('#nm').value.trim()||'Alvinegro';p.avatar=chosen;p.equipped=draft;save();back.remove();profileHub()};back.onclick=e=>{if(e.target===back)back.remove()}}
function bootGlorioso(){
  try{home()}
  catch(err){
    console.error('Falha ao iniciar Glorioso Quiz:',err);
    const root=document.querySelector('#app');
    if(root)root.innerHTML=`<section class="recoveryScreen"><span class="eyebrow">★ MODO DE RECUPERAÇÃO</span><h1>VAMOS RECUPERAR O JOGO</h1><p>O Glorioso Quiz encontrou uma falha ao carregar. Seu progresso continua salvo neste navegador.</p><button class="primary" id="retryBoot">TENTAR NOVAMENTE</button><button class="secondary" id="safeReset">RECARREGAR INTERFACE</button><small>V4.44 • proteção contra tela preta</small></section>`;
    const retry=document.querySelector('#retryBoot'); if(retry)retry.onclick=()=>location.reload();
    const safe=document.querySelector('#safeReset'); if(safe)safe.onclick=()=>{try{localStorage.removeItem('gloriosoRuntimeCache')}catch(e){} location.reload()};
  }
}
bootGlorioso();
